const personaCanUseSecret = `-- name: PersonaCanUseSecret :one
WITH RECURSIVE chain AS (
    SELECT p.id, p.reports_to, 0 AS depth FROM personas p WHERE p.company_id = $1 AND p.id = $3
    UNION ALL
    SELECT p.id, p.reports_to, c.depth + 1 FROM personas p JOIN chain c ON p.id = c.reports_to
    WHERE p.company_id = $1 AND c.depth < 50
)
SELECT EXISTS (
    SELECT 1 FROM secret_collection_items i
    JOIN secret_collection_grants g ON g.collection_id = i.collection_id AND g.permission = 'use'
    WHERE i.company_id = $1 AND i.secret_id = $2
      AND (g.subject_type = 'all_personas'
           OR (g.subject_type = 'persona' AND g.subject_id = $3::uuid)
           OR (g.subject_type = 'persona_tree' AND g.subject_id IN (SELECT id FROM chain)))
)::boolean AS allowed
`

type PersonaCanUseSecretParams struct {
	CompanyID uuid.UUID
	SecretID  uuid.UUID
	PersonaID uuid.UUID
}

// A persona alcança o segredo se alguma coleção que o contém foi concedida (use) a ela, a todas as personas ou a uma
// persona acima dela no organograma (persona_tree). Recursão limitada a 50 níveis, como o organograma (ADR-0068 §2).
func (q *Queries) PersonaCanUseSecret(ctx context.Context, arg PersonaCanUseSecretParams) (bool, error) {
	row := q.db.QueryRow(ctx, personaCanUseSecret, arg.CompanyID, arg.SecretID, arg.PersonaID)
	var allowed bool
	err := row.Scan(&allowed)
	return allowed, err
}

