const userCollectionPermissions = `-- name: UserCollectionPermissions :many
SELECT DISTINCT g.permission FROM secret_collection_items i
JOIN secret_collection_grants g ON g.collection_id = i.collection_id
WHERE i.company_id = $1 AND i.secret_id = $2
  AND g.subject_type = 'user' AND g.subject_id = $3::uuid
`

type UserCollectionPermissionsParams struct {
	CompanyID uuid.UUID
	SecretID  uuid.UUID
	UserID    uuid.UUID
}

// Permissões de um humano sobre um segredo, pelas coleções que o contêm (view/manage).
func (q *Queries) UserCollectionPermissions(ctx context.Context, arg UserCollectionPermissionsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, userCollectionPermissions, arg.CompanyID, arg.SecretID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var permission string
		if err := rows.Scan(&permission); err != nil {
			return nil, err
		}
		items = append(items, permission)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
